import React, { useEffect, useRef, useState } from "react";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import http, { uploadImage } from "../../services/utility";
import { apisPath } from "../../utils/path";
import { useLocation, useNavigate } from "react-router-dom";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import { useDispatch } from "react-redux";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";

export default function AddBlogs() {
  const dispatch = useDispatch();
  const { state } = useLocation();
  const [blogId, setBlogId] = useState(state?.blogId);
  const [editable, setEditable] = useState(state?.editable);
  const [blogData, setBlogData] = useState(state?.data);
  const navigate = useNavigate();
  const newBlogRef = useRef(null);
  const [blogImage, setBlogImage] = useState(null);
  const [body, setBody] = useState({
    images: [],
    heading: "",
    bodyText: "",
    tags: [],
    duration: "",
    category: "",
  });
  const [tags, setTags] = useState("");
  const [hourRead, setHourRead] = useState("0");

  useEffect(() => {
    if (editable) {
      setBody(blogData);
      const resultTag = blogData["tags"]?.join(" ");
      setTags(resultTag);

      const currentDate = new Date();
      const anotherDate = new Date(blogData?.createdAt);
      const timeDifferenceMs = currentDate - anotherDate;
      const timeDifferenceHours = timeDifferenceMs / (1000 * 60 * 60 * 24);
      setHourRead(parseInt(timeDifferenceHours));

      setBlogImage(blogData?.images[0]);
    }
  }, [editable]);

  useEffect(() => {
    if (tags !== "") {
      let tag = tags?.split(" ");
      let bo = { ...body };
      bo["tags"] = tag;
      setBody(bo);
    }
  }, [tags]);

  const handleInputChange = (e) => {
    const { name, value } = e?.target;
    setBody({ ...body, [name]: value });
  };

  const uploadData = async (e) => {
    let data = { ...body };

    data["tags"] = tags?.split(" ");

    await http
      .post(apisPath?.admin?.blogs, data)
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        navigate(-1);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const updateData = async () => {
    let data = { ...body };
    data["tags"] = tags?.split(" ");

    await http
      .put(`${apisPath?.admin?.blogs}/${blogId}`, data)
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        navigate(-1);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  return (
    <div className="add_blogs">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Blogs</h3>
      </div>
      <div className="add_blogs__content">
        <div className="add_blogs__content__cards">
          <div
            className="add_blogs__content__cards__new_blog"
            onClick={() => newBlogRef?.current?.click()}
          >
            <FileUploadIcon />
            <span>Upload blogs thumbnail</span>
          </div>
          <input
            type="file"
            style={{ display: "none" }}
            ref={newBlogRef}
            onChange={async (e) => {
              await uploadImage(e)
                .then((res) => {
                  setBlogImage(res?.url);
                  let bo = { ...body };
                  bo["images"]?.push(res?.url);
                })
                .catch((err) => {
                  console.log(err);
                });
            }}
          />
          <div
            className="add_blogs__content__cards__about"
            style={{
              background: `rgba(0,0,0,0.4) url("${blogImage}") center / cover no-repeat`,
            }}
          >
            <div className="add_blogs__content__cards__about__content">
              <div className="add_blogs__content__cards__about__content__tags">
                {body?.tags?.map((tag, index) => {
                  return (
                    <span
                      className="add_blogs__content__cards__about__content__tags__tag"
                      key={index}
                    >
                      {tag}
                    </span>
                  );
                })}
              </div>
              <h3>{body?.heading}</h3>
              <p>
                {body?.bodyText?.length > 150
                  ? body?.bodyText?.substring(0, 150) + "..."
                  : body?.bodyText}
              </p>

              {body?.duration !== "" && (
                <p>
                  {hourRead} days ago <span>.</span> {body?.duration} minutes
                  read
                </p>
              )}
            </div>
          </div>
        </div>
        <div className="add_blogs__content__heading">
          <label htmlFor="heading">Heading</label>
          <input
            type="text"
            id="heading"
            name="heading"
            value={body?.heading}
            placeholder="Enter here"
            onChange={(el) => handleInputChange(el)}
          />
        </div>
        <div className="add_blogs__content__body_text">
          <label htmlFor="bodyText">Body text</label>
          <textarea
            id="bodyText"
            name="bodyText"
            cols="100"
            rows="10"
            placeholder="Enter here"
            value={body?.bodyText}
            onChange={(el) => handleInputChange(el)}
          ></textarea>
        </div>

        <div className="add_blogs__content__two_input">
          <div className="add_blogs__content__two_input__tag">
            <div className="add_blogs__content__two_input__tag__tooltip">
              <label htmlFor="tags">Tag</label>
              <button title="Type space for multiple tags">i</button>
            </div>
            <input
              type="text"
              id="tags"
              name="tags"
              placeholder="Enter here"
              value={tags}
              onChange={(el) => setTags(el?.target?.value)}
            />
          </div>
          <div className="add_blogs__content__two_input__reading_duration">
            <label htmlFor="duration">Reading duration</label>
            <input
              type="text"
              id="duration"
              name="duration"
              placeholder="MM"
              value={body?.duration}
              onChange={(el) => handleInputChange(el)}
            />
          </div>
        </div>
        <div className="add_blogs__content__category">
          <label htmlFor="category">Category</label>
          <input
            type="text"
            id="category"
            name="category"
            placeholder="Enter here"
            value={body?.category}
            onChange={(el) => handleInputChange(el)}
          />
        </div>
        {editable ? (
          <button className="button-red" onClick={updateData}>
            Update blog
          </button>
        ) : (
          <button className="button-red" onClick={uploadData}>
            Add blog
          </button>
        )}
      </div>
    </div>
  );
}
